	/// Advance one autoregressive position through the block against `cache`.
	///
	/// `input` must be F32 `[batch, model_width]` for the cache's batch size.
	/// Runs the same pre-norm → attention → residual → FFN → residual
	/// sequence as `forward_impl` for one position, with
	/// [`MultiHeadAttention::step`] supplying the cached key/value state.
	/// Inference-only per [`MultiHeadAttention::step`]: an active
	/// `GradientTape` is rejected there, and conditioned blocks are not
	/// admitted for incremental decode.
	///
	/// # Errors
	///
	/// Returns an error for a conditioned block, an active tape, a foreign
	/// or mismatched cache, or a failed child operation.
	pub fn step(&self, input: &Matrix, cache: &mut AttentionCache) -> Result<Matrix> {
		if self.is_adaptively_conditioned() {
			return Err(Error::failed_precondition(
				"TransformerBlock incremental decode does not admit adaptive conditioning",
			));
		}
		let normalized = self.norm_attention.forward(input)?;
		let attended = self.attention.step(&normalized, cache)?;
		let residual = matrix::add(input, &attended)?;
		match &self.feed_forward {
			FeedForward::Dense {
				norm,
				input,
				output,
			} => {
				let normalized = norm.forward(&residual)?;
				let hidden = gelu(&input.forward(&normalized)?)?;
				let projected = output.forward(&hidden)?;
				matrix::add(&residual, &projected)
			}
			FeedForward::Moe(moe) => moe.forward(&residual),
		}
	}

	fn forward_impl(&self, input: &Matrix, additive_mask: Option<&Matrix>) -> Result<Matrix> {
		let normalized = self.norm_attention.forward(input)?;
		let attended = match additive_mask {
			Some(mask) => self.attention.forward_masked(&normalized, mask)?,
			None => self.attention.forward(&normalized)?,
		};
		let residual = matrix::add(input, &attended)?;
		match &self.feed_forward {
			FeedForward::Dense {
				norm,
				input,
				output,
			} => {
				let normalized = norm.forward(&residual)?;
				let hidden = gelu(&input.forward(&normalized)?)?;
				let projected = output.forward(&hidden)?;
				matrix::add(&residual, &projected)
			}
			FeedForward::Moe(moe) => moe.forward(&residual),
		}
	}

