	pub fn new_with_seed(
		vocab_size: usize,
		context_length: usize,
		model_width: usize,
		hidden_width: usize,
		num_layers: usize,
		num_heads: usize,
		epsilon: f32,
		seed: u64,
	) -> Result<Self> {
		Self::new_with_seed_on(
			&Engine::current()?,
			vocab_size,
			context_length,
			model_width,
			hidden_width,
			num_layers,
			num_heads,
			epsilon,
			seed,
		)
	}

